#ifndef SCAMP_IMAGE_HPP
#define SCAMP_IMAGE_HPP
#include "fib.hpp"
#include "scamptrie_base.h"
#include <array>
#include <bitset>
#include <cstdint>
#include <string>
#include <vector>

struct ImageLoc { int stage = -1; uint32_t cell = 0; };
struct ImageFront { uint64_t key; ImageLoc loc; };
struct ImageData {
    ImageLoc root;
    std::vector<ImageFront> front16, front64;
    std::array<uint32_t, RAM_NUM> cells{};
    std::array<std::vector<std::bitset<256>>, RAM_NUM> banks;
    std::vector<uint64_t> bitmaps;
    std::vector<uint32_t> nexthops;
};

class MemoryImage {
public:
    MemoryImage() = default;
    // Validate the complete self-contained image before replacing loaded state.
    // Returns false (and keeps the previous image) on any semantic violation.
    bool load(const ImageData& proposed);
    nexthop_t lookup(ip6_t ip) const;

private:
    ImageData data_;
    Fib fib_;
};

// Semantic validation of a complete packed image. On success the exact prefix
// set carried by the image is returned through out.
bool image_validate(const ImageData& d, Fib& out);

std::string image_word_hex(const std::bitset<256>& bits);
std::bitset<256> image_word_from_hex(const std::string& text);
#endif
